<?php require '../config/db.php';require '../includes/functions.php';$blog=(int)($_POST['blog_id']??0);$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$comment=trim($_POST['comment']??'');if(!$blog||strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($comment)<3)json_response(false,'Check your comment details.',[],422);$pdo->prepare('INSERT INTO blog_comments(blog_id,name,email,comment,status) VALUES(?,?,?,?,\'approved\')')->execute([$blog,$name,$email,$comment]);json_response(true,'Comment posted successfully.');